import type { Nicho } from './schema.ts';

/** Path of the share image generated by src/pages/og.png.ts. */
export const CAMINHO_OG = '/og.png';
export const LARGURA_OG = 1200;
export const ALTURA_OG = 630;

/** Absolute URL of a path on the site, or undefined when the niche has no site.url. */
export function urlAbsoluta(site: string | undefined, caminho: string): string | undefined {
  return site ? new URL(caminho, site).href : undefined;
}

/** Open Graph locale from a BCP 47 tag: "pt-BR" -> "pt_BR". */
export function localeOg(idioma: string): string {
  const [lingua = '', regiao] = idioma.split(/[-_]/);
  return regiao ? `${lingua.toLowerCase()}_${regiao.toUpperCase()}` : lingua.toLowerCase();
}

/** Short line shown on the share image: the hero title, or the site title. */
export function chamadaPrincipal(nicho: Nicho): string {
  const hero = nicho.secoes.find((secao) => secao.tipo === 'hero' && secao.ativo);
  return hero?.tipo === 'hero' ? hero.titulo : nicho.site.titulo;
}

type Objeto = Record<string, unknown>;

/** schema.org JSON-LD for the home page: the business plus a FAQPage from the active FAQ sections. */
export function gerarJsonLd(nicho: Nicho): Objeto {
  const { site, contato } = nicho;
  const url = urlAbsoluta(site.url, '/');
  const negocio: Objeto = {
    '@type': site.schema_tipo ?? 'LocalBusiness',
    '@id': url && `${url}#negocio`,
    name: site.nome,
    description: site.descricao,
    url,
    image: urlAbsoluta(site.url, CAMINHO_OG),
    telephone: contato.telefone ?? `+${contato.whatsapp}`,
    email: contato.email,
  };
  if (contato.endereco) {
    const { endereco } = contato;
    negocio.address = {
      '@type': 'PostalAddress',
      streetAddress: endereco.bairro ? `${endereco.logradouro} - ${endereco.bairro}` : endereco.logradouro,
      addressLocality: endereco.cidade,
      addressRegion: endereco.uf,
      postalCode: endereco.cep,
      addressCountry: 'BR',
    };
  }
  if (contato.horario?.length) negocio.openingHours = contato.horario;

  const perguntas = nicho.secoes.flatMap((secao) => (secao.tipo === 'faq' && secao.ativo ? secao.itens : []));
  const grafo: Objeto[] = [negocio];
  if (perguntas.length > 0) {
    grafo.push({
      '@type': 'FAQPage',
      mainEntity: perguntas.map((item) => ({
        '@type': 'Question',
        name: item.pergunta,
        acceptedAnswer: { '@type': 'Answer', text: item.resposta },
      })),
    });
  }
  return { '@context': 'https://schema.org', '@graph': grafo };
}

/**
 * JSON for an inline <script type="application/ld+json">: `<`, `>` and `&` are escaped
 * as \u00XX so the content can never close the script tag (JSON.stringify drops undefined).
 */
export function serializarJsonLd(dados: unknown): string {
  return JSON.stringify(dados)
    .replaceAll('<', '\\u003c')
    .replaceAll('>', '\\u003e')
    .replaceAll('&', '\\u0026');
}

